definition.script:
pipeline {
    agent { label 'windows' }

    environment {
        VCPKG_ROOT              = 'C:\\vcpkg'
        VCPKG_INSTALLATION_ROOT = 'C:\\vcpkg'
        COMPASS_VIEWER          = '1'
        LIBCLANG_PATH           = 'C:\\Program Files\\LLVM\\bin'
    }

    stages {
        stage('Checkout') {
            steps {
                checkout([
                    $class: 'GitSCM',
                    branches: [[name: '*/compass-rmm-v3']],
                    extensions: [[$class: 'SubmoduleOption', recursiveSubmodules: true, parentCredentials: true]],
                    userRemoteConfigs: [[
                        url: 'https://github.com/Davinci-Technology/rustdesk.git'
                    ]]
                ])
            }
        }

        stage('Check Tools') {
            steps {
                bat '''call "C:\\Program Files (x86)\\Microsoft Visual Studio\\2022\\BuildTools\\VC\\Auxiliary\\Build\\vcvarsall.bat" x64
set VCPKG_ROOT=C:\\vcpkg
set PATH=%USERPROFILE%\\.cargo\\bin;C:\\flutter\\bin;%PATH%
rustc --version
cargo --version
flutter --version
cargo expand --version
flutter_rust_bridge_codegen --version
where link.exe'''
            }
        }

        stage('Flutter Rust Bridge Codegen') {
            steps {
                powershell '''
                    $lines = Get-Content Cargo.toml
                    $out = @()
                    $inBin = $false
                    foreach ($line in $lines) {
                        if ($line -match '^default-run = ') {
                            $out += "#$line"
                            continue
                        }
                        if ($line -match '^\\[\\[bin\\]\\]') {
                            $inBin = $true
                            $out += "#$line"
                            continue
                        }
                        if ($inBin -and $line -match '^(name|path|required-features) = ') {
                            $out += "#$line"
                            continue
                        }
                        if ($inBin -and $line -match '^\\s*$') {
                            $inBin = $false
                        }
                        if ($line -match '^\\[package\\]') {
                            $out += $line
                            $out += 'autobins = false'
                            continue
                        }
                        if ($line -eq 'default = ["use_dasp"]') {
                            $out += 'default = ["use_dasp", "flutter"]'
                            continue
                        }
                        $out += $line
                    }
                    $out | Set-Content Cargo.toml
                '''
                bat '''call "C:\\Program Files (x86)\\Microsoft Visual Studio\\2022\\BuildTools\\VC\\Auxiliary\\Build\\vcvarsall.bat" x64
set VCPKG_ROOT=C:\\vcpkg
set PATH=%USERPROFILE%\\.cargo\\bin;C:\\flutter\\bin;%PATH%
cd flutter && flutter pub get && cd ..'''
                bat '''call "C:\\Program Files (x86)\\Microsoft Visual Studio\\2022\\BuildTools\\VC\\Auxiliary\\Build\\vcvarsall.bat" x64
set VCPKG_ROOT=C:\\vcpkg
set PATH=%USERPROFILE%\\.cargo\\bin;C:\\flutter\\bin;%PATH%
flutter_rust_bridge_codegen --rust-input ./src/flutter_ffi.rs --dart-output ./flutter/lib/generated_bridge.dart --rust-crate-dir . --rust-output ./src/bridge_generated.rs --skip-deps-check --class-name Rustdesk'''
                bat 'git checkout -- Cargo.toml'
                powershell '''
                    $lines = (Get-Content flutter/lib/generated_bridge.dart).Count
                    Write-Host "generated_bridge.dart: $lines lines"
                    if ($lines -lt 1000) { throw "Codegen failed: only $lines lines" }
                '''
            }
        }

        stage('Build compass-rmm.exe') {
            steps {
                bat '''call "C:\\Program Files (x86)\\Microsoft Visual Studio\\2022\\BuildTools\\VC\\Auxiliary\\Build\\vcvarsall.bat" x64
set VCPKG_ROOT=C:\\vcpkg
set PATH=%USERPROFILE%\\.cargo\\bin;C:\\flutter\\bin;%PATH%
cargo build --bin compass-rmm --features compass-rmm --release'''
            }
        }

        stage('Build librustdesk.dll') {
            steps {
                bat '''call "C:\\Program Files (x86)\\Microsoft Visual Studio\\2022\\BuildTools\\VC\\Auxiliary\\Build\\vcvarsall.bat" x64
set VCPKG_ROOT=C:\\vcpkg
set PATH=%USERPROFILE%\\.cargo\\bin;C:\\flutter\\bin;%PATH%
cargo build --lib --features compass-rmm,flutter --release'''
            }
        }

        stage('Build Flutter Viewer') {
            steps {
                bat '''call "C:\\Program Files (x86)\\Microsoft Visual Studio\\2022\\BuildTools\\VC\\Auxiliary\\Build\\vcvarsall.bat" x64
set VCPKG_ROOT=C:\\vcpkg
set PATH=%USERPROFILE%\\.cargo\\bin;C:\\flutter\\bin;%PATH%
cd flutter && flutter pub get && flutter build windows --release'''
            }
        }

        stage('Package') {
            steps {
                powershell '''
                    New-Item -ItemType Directory -Force -Path artifacts | Out-Null

                    # compass-rmm.zip - standalone headless agent
                    Compress-Archive -Path target\\release\\compass-rmm.exe -DestinationPath artifacts\\compass-rmm.zip -Force

                    # compass-viewer.zip - viewer + all runtime deps
                    Compress-Archive -Path flutter\\build\\windows\\x64\\runner\\Release\\* -DestinationPath artifacts\\compass-viewer.zip -Force
                '''
                archiveArtifacts artifacts: 'artifacts/*.zip', fingerprint: true
            }
        }
    }

    post {
        always {
            cleanWs()
        }
        success {
            echo 'Build succeeded! Artifacts archived.'
        }
    }
}
